pub fn decode_shift(s: Vec<char>) -> Vec<char> {
    const ALPHA_LEN: u8 = 26;
    const SHIFT: u8 = 5;
    const ASCII_A: u8 = b'a';

    s.into_iter()
        .map(|c| {
            // Convert 'a'..'z' to 0..25
            let idx = c as u8 - ASCII_A;
            // Subtract 5 with wrap-around modulo 26
            let decoded_idx = (idx + ALPHA_LEN - SHIFT) % ALPHA_LEN;
            // Convert back to 'a'..'z'
            (ASCII_A + decoded_idx) as char
        })
        .collect()
}

